-- Ftour Jomaa – Generated seed data
-- DO NOT EDIT: regenerate with tools/gen_schema.py

CREATE TABLE IF NOT EXISTS Dish (
    dishId INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    nameAr TEXT,
    type TEXT NOT NULL CHECK(type IN ('STARTER','MAIN','DESSERT')),
    tone TEXT DEFAULT 'harissa',
    imageUri TEXT,
    baseServings INTEGER DEFAULT 4
);

CREATE TABLE IF NOT EXISTS IngredientLibrary (
    ingredientId INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    nameAr TEXT,
    category TEXT NOT NULL CHECK(category IN ('VEGETABLE','SPICE','MEAT','LIQUID','PASTRY','OTHER')),
    defaultUnit TEXT DEFAULT 'GR'
);

CREATE TABLE IF NOT EXISTS DishIngredientCrossRef (
    dishId INTEGER NOT NULL,
    ingredientId INTEGER NOT NULL,
    quantity REAL NOT NULL,
    PRIMARY KEY (dishId, ingredientId),
    FOREIGN KEY (dishId) REFERENCES Dish(dishId) ON DELETE CASCADE,
    FOREIGN KEY (ingredientId) REFERENCES IngredientLibrary(ingredientId)
);

CREATE TABLE IF NOT EXISTS WeeklyPlanning (
    planId INTEGER PRIMARY KEY AUTOINCREMENT,
    weekId TEXT NOT NULL,
    dayId INTEGER NOT NULL CHECK(dayId >= 0 AND dayId <= 6),
    dishId INTEGER,
    plannedServings INTEGER DEFAULT 4,
    mealType TEXT NOT NULL CHECK(mealType IN ('STARTER','MAIN','DESSERT')),
    FOREIGN KEY (dishId) REFERENCES Dish(dishId),
    UNIQUE(weekId, dayId, mealType)
);

CREATE INDEX IF NOT EXISTS idx_dish_type ON Dish(type);
CREATE INDEX IF NOT EXISTS idx_ingredient_category ON IngredientLibrary(category);
CREATE INDEX IF NOT EXISTS idx_weekly_planning_week ON WeeklyPlanning(weekId);
CREATE INDEX IF NOT EXISTS idx_weekly_planning_dish ON WeeklyPlanning(dishId);

